-- Demo data. Runs after 01-schema.sql on first start of an empty volume.
-- DEV ONLY: remove this file (or the mount) for any real deployment.
--
-- Every demo user logs in with the password:  Password123!
-- (stored as a bcrypt hash, generated by pgcrypto; compatible with bcrypt/bcryptjs).
--
--   Validators: carol@example.com, victor@example.com
--   Requesters: alice@example.com, bob@example.com, dave@example.com, erin@example.com
--
-- This file is the only place demo data is created; the backend does not seed anything.
-- The e2e suite (e2e/support/api.ts) relies on alice/bob (Requester) and carol (Validator).
--
-- Dates are relative to the day the database is initialised, so the demo requests
-- stay in the future (a couple of approved ones are in the past as history).

CREATE EXTENSION IF NOT EXISTS pgcrypto;

INSERT INTO users (id, name, email, password, role) VALUES
    ('00000000-0000-4000-8000-000000000001', 'Carol Validator', 'carol@example.com',            crypt('Password123!', gen_salt('bf', 10)), 'Validator'),
