    ('00000000-0000-4000-8000-000000000012', 'Bob Johnson',      'bob@example.com',              crypt('Password123!', gen_salt('bf', 10)), 'Requester'),
    ('00000000-0000-4000-8000-000000000013', 'Erin Nguyen',      'erin@example.com',             crypt('Password123!', gen_salt('bf', 10)), 'Requester'),
